    for (int i = threadIdx.x; i < tile_size; i += blockDim.x)
        smem[i] = K[tile_start + i];
    __syncthreads();  // CTA-level barrier: 等待所有 4 warps 完成加载
    // Compute attention using shared memory data
    ...
}

// Virtual decode CTA 改造 (warp-level barrier):
__device__ void decode_virtual_cta(int virtual_cta_id, ...) {
    // 每个 virtual CTA 独立加载和处理自己的 K/V tile 段
    int warp_id = virtual_cta_id;  // virtual CTA 映射到 warp
    int warp_tile_offset = warp_id * (tile_size / 4);

    for (int i = threadIdx.x % 32; i < tile_size / 4; i += 32)
        smem[warp_tile_offset + i] = K[warp_tile_offset + i];
    __syncwarp();  // Warp-level barrier: 仅同步当前 warp 的 32 threads

    // 使用自己的 shared memory 段计算 attention
    ...
